const brands = [
  { id: 'dax-collective', name: 'The Dax Collective', outputs: ['posts', 'videos', 'designs'] },
  { id: 'dax-the-traveler', name: 'Dax the Traveler', outputs: ['posts', 'videos', 'itineraries', 'designs'] },
  { id: 'time-zone-travelers', name: 'Time-Zone Travelers', outputs: ['posts', 'videos', 'itineraries', 'designs', 'stickers'] },
  { id: 'ani-dax', name: 'Ani-Dax', outputs: ['posts', 'videos', 'designs', 'stickers'] },
  { id: 'gods-vessel', name: "God's Vessel", outputs: ['posts', 'videos', 'merch', 'stickers', 'designs'] }
];

const outputAgents = {
  posts: 'social_post_agent',
  videos: 'video_concept_agent',
  itineraries: 'itinerary_agent',
  merch: 'merch_design_agent',
  stickers: 'sticker_design_agent',
  designs: 'brand_design_agent'
};

const items = [];
for (const brand of brands) {
  for (const outputType of brand.outputs) {
    items.push({
      json: {
        brand: brand.id,
        brandName: brand.name,
        outputType,
        primaryAgent: outputAgents[outputType],
        supportAgents: ['content_strategy_agent', 'asset_management_agent', 'compliance_qa_agent'],
        publishAllowed: false,
        reviewStatus: 'manual_review_required',
        requiredFields: ['brand', 'platform', 'objective', 'cta', 'assets_needed', 'review_status'],
        createdAt: new Date().toISOString()
      }
    });
  }
}

return items;

const items = $input.all();
const summary = {
  workflow: 'DAX-00 AI Agent Master Router - Manual Review',
  totalRoutes: items.length,
  routesByType: {},
  routesByBrand: {},
  publishingEnabled: false,
  reviewStatus: 'manual_review_required',
  nextSafeStep: 'Pick one route, create a draft package, run QA, then approve manually before publishing.',
  generatedAt: new Date().toISOString()
};

for (const item of items) {
  const type = item.json.outputType;
  const brand = item.json.brand;
  summary.routesByType[type] = (summary.routesByType[type] || 0) + 1;
  summary.routesByBrand[brand] = (summary.routesByBrand[brand] || 0) + 1;
}

return [{ json: summary }];
